/* =====================================================================
   ✏️ TUTOR GUIDE: AP U.S. HISTORY (shown on tutor-math.html, tutors only)
   Follows the 9 periods of the College Board APUSH course, plus a
   writing-skills unit (SAQ, DBQ, LEQ).
   Same fields as the other tutor files, used for history:
     vocab    = key terms & people     steps   = how to think/answer
     examples = sample prompts with model answers
     mistakes = common errors          check   = quick recall questions
   Visuals marked "USV_..." are timelines drawn at the bottom of this file.
   Exam weightings are approximate; check the current College Board CED.
   ===================================================================== */
(window.TUTOR_UNITS = window.TUTOR_UNITS || []).push(

/* ---------------- PERIOD 1 ---------------- */
{ id: "us-01", course: "AP U.S. History", unit: 1, title: "Period 1 (1491–1607): Native Societies & European Contact", standards: "≈ 4–6% of the exam",
  bigIdea: "Before Europeans arrived, American Indian societies were diverse and adapted to their environments (maize farming in the Southwest, mixed farming and hunting in the East, mobile hunting on the Plains). Contact with Europeans after 1492 caused the Columbian Exchange, which transformed both hemispheres. Spain built an empire based on extracting labor and wealth, which created new racial hierarchies and debates about how to treat Native peoples.",
  tips: "This period is small on the exam, but it sets up themes that repeat all year: <b>environment shapes society</b>, <b>contact causes exchange AND conflict</b>, and <b>labor systems create social hierarchies</b>. Have the student connect each term to one of those themes.",
  vocab: [
    ["maize cultivation", "Corn farming spread north from Mexico. It supported larger, settled societies (Pueblo in the Southwest)."],
    ["Columbian Exchange", "Transfer of plants, animals, people, and diseases between the Americas and Europe/Africa (horses, cattle, wheat → Americas; maize, potatoes, tobacco → Europe; smallpox devastated Native populations)."],
    ["encomienda system", "Spanish labor system: colonists were granted Native laborers in exchange for “protecting” and converting them. In practice, forced labor."],
    ["casta system", "Spanish racial hierarchy based on mixtures of Spanish, Native, and African ancestry."],
    ["Valladolid debate (1550–1551)", "Bartolomé de las Casas (Natives are fully human, should not be enslaved) vs. Juan Ginés de Sepúlveda (Natives could be conquered)."],
    ["Atlantic slave trade", "As Native populations fell, Europeans forced enslaved Africans to the Americas, especially for sugar plantations."],
    ["mercantilism (early)", "European powers sought gold, silver, and colonies to increase national wealth."]
  ],
  steps: [
    { name: "Answering a Period 1 question", list: ["Identify the group (which Native society, which European power).", "Connect to the environment (what did geography allow them to do?).", "Explain the effect of contact: exchange, disease, labor, conflict, or adaptation.", "Use a specific example (a term from the vocabulary list)."] }
  ],
  examples: [
    { q: "SAQ: Briefly describe ONE way the Columbian Exchange changed life in the Americas.", steps: ["A (answer): Name the change directly.", "C (cite): Give a specific example.", "E (explain): Show how the example proves the change."], answer: "The Columbian Exchange introduced horses to the Americas. Plains Indians such as the Lakota adopted horses, which made them far more mobile and transformed hunting buffalo into the center of their economy and culture." },
    { q: "SAQ: Briefly explain ONE way Spanish colonization created a new social structure in the Americas.", steps: ["Answer: Spain created a racial hierarchy.", "Cite: the casta system.", "Explain: people were ranked by their mix of Spanish, Native, and African ancestry, with Spanish-born at the top."], answer: "The Spanish casta system ranked people by ancestry, with peninsulares (born in Spain) at the top and Native and African peoples near the bottom, so race became tied to social and legal status." },
    { q: "Which development best explains the rapid decline of Native populations after 1492?", steps: ["Look for the cause with the biggest effect.", "Warfare and forced labor mattered, but they killed far fewer people than disease.", "Native peoples had no immunity to diseases like smallpox."], answer: "The spread of European diseases such as smallpox" }
  ],
  mistakes: [
    ["Describes all Native Americans as the same.", "“Which Native society? How did the environment make them different from others?”"],
    ["Says the Columbian Exchange only went one way.", "“What came from the Americas to Europe? (maize, potatoes, tobacco)”"],
    ["Gives an answer without a specific example.", "“Can you name a specific term, group, or event that proves it?”"],
    ["Retells events without explaining their effect.", "“So what? What changed because of that?”"]
  ],
  ask: ["Which group are we talking about?", "How did the environment shape their way of life?", "What changed because of contact?", "What specific example proves your point?", "Can you connect this to a later period?"],
  check: [
    { q: "Name one item that went from the Americas to Europe.", a: "Maize, potatoes, tomatoes, tobacco, or cacao" },
    { q: "What was the encomienda system?", a: "A Spanish system of forced Native labor in exchange for “protection” and conversion" },
    { q: "Who argued against Native enslavement at Valladolid?", a: "Bartolomé de las Casas" }
  ],
  visual: "USV_P1" },

/* ---------------- PERIOD 2 ---------------- */
{ id: "us-02", course: "AP U.S. History", unit: 2, title: "Period 2 (1607–1754): Colonial Societies", standards: "≈ 6–8% of the exam",
  bigIdea: "Different European powers and different British colonies developed in different ways. The Chesapeake grew tobacco and shifted from indentured servants to enslaved Africans; New England was built around family farms, towns, and Puritan religion; the Middle Colonies were diverse and commercial; the South used plantation slavery. Britain tied the colonies to its economy (mercantilism) but often left them alone (salutary neglect), and colonists developed their own self-government.",
  tips: "Use a <b>comparison chart</b>: columns for Chesapeake, New England, Middle, and Southern colonies; rows for economy, labor, religion, and relations with Native peoples. “Compare” questions on this period are very common, and the chart gives the student ready-made similarities and differences.",
  vocab: [
    ["Jamestown (1607)", "First permanent English colony (Virginia), saved economically by tobacco."],
    ["headright system", "Land given to people who paid for a laborer’s passage; encouraged indentured servitude."],
    ["indentured servants", "Workers who agreed to labor for several years in exchange for passage to America."],
    ["Bacon’s Rebellion (1676)", "Frontier farmers (including former servants) rebelled against Virginia’s governor. Afterward, planters relied more on enslaved Africans than on servants."],
    ["Puritans / Massachusetts Bay (1630)", "Religious settlers seeking a “city upon a hill”; towns, family farms, high literacy."],
    ["Pueblo Revolt (1680)", "Pueblo people drove the Spanish out of New Mexico for about 12 years."],
    ["mercantilism & Navigation Acts", "Colonies existed to enrich Britain; laws required certain goods to be traded only through Britain."],
    ["salutary neglect", "Britain loosely enforced its trade laws, letting colonies govern themselves."],
    ["First Great Awakening (1730s–1740s)", "Religious revival (Jonathan Edwards, George Whitefield) that challenged established churches and authority."],
    ["Stono Rebellion (1739)", "Slave uprising in South Carolina that led to harsher slave codes."]
  ],
  steps: [
    { name: "Answering a comparison question", list: ["Name the two regions or groups being compared.", "Give a clear similarity OR difference (whatever the prompt asks).", "Support with a specific example from each side.", "Explain WHY they were similar or different (environment, religion, economy, motives)."] }
  ],
  examples: [
    { q: "SAQ: Briefly explain ONE difference between the Chesapeake and New England colonies.", steps: ["Answer: they had different economies and labor systems.", "Cite: Chesapeake → tobacco plantations; New England → small family farms and trade.", "Explain the cause: the Chesapeake’s climate and soil suited cash crops, while New England’s rocky soil and Puritan town settlement encouraged family farming."], answer: "The Chesapeake built its economy on tobacco plantations worked by indentured servants and later enslaved Africans, while New England developed small family farms and trade because of its rocky soil and Puritan settlement in towns." },
    { q: "SAQ: Briefly explain ONE effect of Bacon’s Rebellion.", steps: ["Answer: planters shifted away from indentured servants.", "Cite: the rebellion included poor former servants angry about land and frontier policy.", "Explain: elites saw servants as a threat, so they turned to enslaved Africans, which hardened racial slavery."], answer: "After Bacon’s Rebellion, Virginia planters relied more on enslaved Africans instead of indentured servants, which helped make slavery a permanent, race-based system in the Chesapeake." },
    { q: "Which best describes the effect of the First Great Awakening?", steps: ["Think about authority: preachers like Whitefield told ordinary people they could judge their own faith.", "That weakened traditional church leaders and encouraged new denominations."], answer: "It challenged traditional religious authority and encouraged colonists to question established leaders." }
  ],
  mistakes: [
    ["Treats all 13 colonies as the same.", "“Which region? How was its economy different from the others?”"],
    ["Says the Puritans came for religious freedom for everyone.", "“Did they tolerate other religions? What happened to Anne Hutchinson and Roger Williams?”"],
    ["Mixes up the Great Awakening and the Enlightenment.", "“One was religious emotion, one was reason and science. Which is which?”"],
    ["Gives a cause without the result (or the reverse).", "“What happened BECAUSE of that?”"]
  ],
  ask: ["Which region are we in? What was its main economy?", "What labor system did it use? Why?", "How did the colonists relate to Britain at this time?", "How did they interact with Native peoples?", "Is this question asking for a similarity or a difference?"],
  check: [
    { q: "What crop saved Jamestown economically?", a: "Tobacco" },
    { q: "What was salutary neglect?", a: "Britain loosely enforcing trade laws, letting colonies self-govern" },
    { q: "Which revolt drove the Spanish from New Mexico in 1680?", a: "The Pueblo Revolt" }
  ],
  visual: "USV_P2" },

/* ---------------- PERIOD 3 ---------------- */
{ id: "us-03", course: "AP U.S. History", unit: 3, title: "Period 3 (1754–1800): Revolution & the New Nation", standards: "≈ 10–17% of the exam",
  bigIdea: "Britain’s victory in the French and Indian War left it in debt, so it ended salutary neglect and taxed the colonies. Colonists, influenced by Enlightenment ideas about natural rights, resisted and eventually declared independence. After winning, Americans struggled to build a government: the weak Articles of Confederation were replaced by the Constitution, and debates between Federalists and Democratic-Republicans created the first political parties.",
  tips: "This period is heavily tested. Help the student build a <b>cause-and-effect chain</b>: French and Indian War → debt → taxes (Stamp Act) → “no taxation without representation” → protests → war → independence → Articles (too weak) → Shays’ Rebellion → Constitution. If they can explain each arrow, they understand the period.",
  vocab: [
    ["French and Indian War (1754–1763)", "Britain vs. France for North America. Britain won but went deep into debt."],
    ["Proclamation of 1763", "Banned colonial settlement west of the Appalachians; angered colonists."],
    ["Stamp Act (1765)", "Direct tax on printed materials. Led to boycotts and the slogan “no taxation without representation.”"],
    ["Common Sense (1776)", "Thomas Paine’s pamphlet arguing for independence in plain language."],
    ["Declaration of Independence (1776)", "Jefferson’s statement of natural rights (life, liberty, pursuit of happiness) and grievances against the king."],
    ["Articles of Confederation", "First national government: no power to tax, no executive, weak central government."],
    ["Shays’ Rebellion (1786–1787)", "Massachusetts farmers’ uprising over debt; showed the Articles were too weak."],
    ["Constitution (1787) & compromises", "Great Compromise (House by population, Senate equal); Three-Fifths Compromise (enslaved people counted as 3/5 for representation)."],
    ["Federalists vs. Anti-Federalists", "Supporters of the Constitution (The Federalist Papers) vs. opponents who wanted a Bill of Rights (added 1791)."],
    ["Hamilton vs. Jefferson", "Hamilton: strong federal government, national bank, loose interpretation. Jefferson: states’ rights, farmers, strict interpretation."],
    ["Republican motherhood", "Women’s role was to raise virtuous citizens for the republic."]
  ],
  steps: [
    { name: "Answering a causation question", list: ["Identify the event the prompt is about.", "Name a specific cause (or effect).", "Explain HOW the cause led to the event (the ‘because’ link).", "For an essay: rank causes or show both short-term and long-term causes for complexity."] }
  ],
  examples: [
    { q: "SAQ: Briefly explain ONE cause of the American Revolution.", steps: ["Answer: British taxation after the French and Indian War.", "Cite: the Stamp Act of 1765.", "Explain: colonists believed only their own elected assemblies could tax them, so the tax seemed to violate their rights as Englishmen."], answer: "After the French and Indian War left Britain in debt, Parliament passed the Stamp Act (1765). Colonists argued this was taxation without representation, which led to boycotts and growing resistance that eventually became a movement for independence." },
    { q: "SAQ: Briefly explain ONE reason the Articles of Confederation were replaced.", steps: ["Answer: the national government was too weak.", "Cite: Shays’ Rebellion.", "Explain: Congress couldn’t raise an army or taxes to respond, which convinced leaders a stronger central government was needed."], answer: "The Articles gave Congress no power to tax or enforce laws. When Shays’ Rebellion broke out in 1786, the national government couldn’t respond, which convinced leaders to write a stronger Constitution in 1787." },
    { q: "Thesis practice (LEQ): Evaluate the extent to which the American Revolution changed American society (1775–1800).", steps: ["A thesis must make a defensible claim AND give a line of reasoning.", "Add complexity: what changed AND what stayed the same.", "Example structure: “Although X changed, Y remained, because Z.”"], answer: "“Although the Revolution changed American politics by replacing a monarchy with a republic based on natural rights, it did little to change society for women and enslaved people, who were still excluded from those rights.”" }
  ],
  mistakes: [
    ["Says the colonists rebelled because taxes were too high.", "“British taxes were actually low. What was the real complaint? (representation and rights)”"],
    ["Mixes up the Declaration and the Constitution.", "“Which one declared independence (1776), and which one set up the government (1787)?”"],
    ["Says the Three-Fifths Compromise was about voting rights.", "“It was about counting population for representation in Congress. Who benefited?”"],
    ["Writes a thesis that just restates the prompt.", "“What is your argument, and what are your reasons?”"]
  ],
  ask: ["What came right before this event? What did it cause?", "Which Enlightenment idea shows up here?", "Was the national government strong or weak at this point?", "Who agreed and who disagreed? Why?", "Did this change things for everyone, or just some people?"],
  check: [
    { q: "Who wrote Common Sense?", a: "Thomas Paine" },
    { q: "What was the Great Compromise?", a: "House based on population, Senate equal per state" },
    { q: "What did Anti-Federalists demand?", a: "A Bill of Rights" }
  ],
  visual: "USV_P3" },

/* ---------------- PERIOD 4 ---------------- */
{ id: "us-04", course: "AP U.S. History", unit: 4, title: "Period 4 (1800–1848): Democracy, Markets & Reform", standards: "≈ 10–17% of the exam",
  bigIdea: "The young republic expanded democracy (for white men), its territory, and its economy. The Market Revolution (canals, railroads, factories, commercial farming) connected regions but made them more different: the North industrialized while the South relied more than ever on cotton and slavery. Reform movements, often inspired by the Second Great Awakening, pushed to perfect society (abolition, women’s rights, temperance).",
  tips: "Have the student organize this period into <b>three threads</b>: politics (Jefferson, Marshall Court, Jackson), economy (Market Revolution, cotton), and society (Second Great Awakening, reform, Indian Removal). Most questions ask how two threads affected each other, for example how the Market Revolution increased sectional tension.",
  vocab: [
    ["Marbury v. Madison (1803)", "Established judicial review: the Supreme Court can strike down laws as unconstitutional."],
    ["Louisiana Purchase (1803)", "Jefferson doubled the nation’s size, despite his strict-construction beliefs."],
    ["War of 1812", "War with Britain; increased nationalism and domestic manufacturing."],
    ["Missouri Compromise (1820)", "Missouri slave, Maine free; banned slavery north of 36°30′ in the Louisiana Territory."],
    ["Monroe Doctrine (1823)", "Warned Europe not to colonize the Western Hemisphere."],
    ["Market Revolution", "Shift to a market economy: Erie Canal (1825), railroads, Lowell textile mills, cotton gin."],
    ["Jacksonian democracy", "Expanded voting for white men (end of property requirements), spoils system, opposition to the national bank."],
    ["Indian Removal Act (1830) / Trail of Tears", "Forced relocation of Southeastern nations (like the Cherokee) west of the Mississippi."],
    ["Nullification crisis (1832)", "South Carolina claimed it could cancel a federal tariff; Jackson threatened force."],
    ["Second Great Awakening", "Religious revival that inspired reform movements (abolition, temperance, education)."],
    ["Seneca Falls Convention (1848)", "Women’s rights meeting; Declaration of Sentiments (Elizabeth Cady Stanton)."]
  ],
  steps: [
    { name: "Answering a continuity and change question", list: ["Describe what things were like at the start of the period.", "Describe what changed (with evidence) and what stayed the same (with evidence).", "Explain WHY the change happened.", "Make a judgment: was it more change or more continuity?"] }
  ],
  examples: [
    { q: "SAQ: Briefly explain ONE way the Market Revolution affected the United States.", steps: ["Answer: it tied the North and Midwest together economically.", "Cite: the Erie Canal (1825).", "Explain: cheap transportation let Midwestern farmers ship crops east and buy Northern goods."], answer: "The Erie Canal (1825) connected Midwestern farms to Northeastern cities, lowering shipping costs and linking the two regions’ economies, while the South stayed focused on cotton, which increased sectional differences." },
    { q: "SAQ: Briefly explain ONE limit of “Jacksonian democracy.”", steps: ["Answer: democracy expanded only for white men.", "Cite: the Indian Removal Act (1830) / Trail of Tears.", "Explain: the same era that expanded white male voting forced Native nations off their land."], answer: "While Jacksonian democracy expanded voting for white men, Jackson also enforced the Indian Removal Act (1830), forcing the Cherokee and others west on the Trail of Tears, so democracy did not include Native Americans, women, or enslaved people." },
    { q: "Which best explains the rise of reform movements in the 1830s–1840s?", steps: ["Look for the religious connection: the Second Great Awakening taught that people could improve themselves and society.", "That belief inspired abolitionists, temperance reformers, and women’s rights activists."], answer: "The Second Great Awakening’s belief that individuals and society could be perfected" }
  ],
  mistakes: [
    ["Says Jackson expanded democracy for everyone.", "“Who could vote? Who couldn’t? What happened to the Cherokee?”"],
    ["Thinks the Missouri Compromise ended the slavery debate.", "“It calmed it for a while. What happened when new territories were added later?”"],
    ["Confuses the First and Second Great Awakenings.", "“Which century? What did the second one lead to (reform)?”"],
    ["Ignores the South in the Market Revolution.", "“Where did the cotton for the Lowell mills come from?”"]
  ],
  ask: ["Is this about politics, the economy, or society?", "Who gained from this change? Who lost?", "How did this increase or reduce tension between North and South?", "What religious ideas connect to this reform?", "How did this period change from the one before?"],
  check: [
    { q: "What did Marbury v. Madison establish?", a: "Judicial review" },
    { q: "What line did the Missouri Compromise set?", a: "36°30′" },
    { q: "Where was the 1848 women’s rights convention?", a: "Seneca Falls, New York" }
  ],
  visual: "USV_P4" },

/* ---------------- PERIOD 5 ---------------- */
{ id: "us-05", course: "AP U.S. History", unit: 5, title: "Period 5 (1844–1877): Expansion, Civil War & Reconstruction", standards: "≈ 10–17% of the exam",
  bigIdea: "Manifest Destiny and the Mexican-American War added huge territory, and the question of whether slavery could expand there tore the country apart. A series of compromises failed, the Republican Party formed to stop slavery’s spread, and Lincoln’s election led Southern states to secede. The Union won the Civil War and ended slavery. Reconstruction tried to rebuild the South and protect the rights of freedpeople, but it ended in 1877 with many of those gains rolled back.",
  tips: "The road to the Civil War is a classic <b>chain of events</b>. Have the student put these in order with one sentence each: Mexican-American War → Wilmot Proviso → Compromise of 1850 (Fugitive Slave Act) → Kansas-Nebraska Act → Bleeding Kansas → Dred Scott → Lincoln’s election → secession. The common thread: <b>the expansion of slavery into the West</b>.",
  vocab: [
    ["Manifest Destiny", "The belief that Americans were destined to expand across the continent."],
    ["Mexican-American War (1846–1848)", "U.S. gained California and the Southwest (Treaty of Guadalupe Hidalgo)."],
    ["Wilmot Proviso (1846)", "Proposed banning slavery in land won from Mexico; passed the House but failed in the Senate, and deepened the divide."],
    ["Compromise of 1850", "California free; popular sovereignty in other territories; strict Fugitive Slave Act."],
    ["Kansas-Nebraska Act (1854)", "Popular sovereignty in Kansas and Nebraska; repealed the Missouri Compromise line; led to “Bleeding Kansas” and the Republican Party."],
    ["Dred Scott v. Sandford (1857)", "Supreme Court: Black people were not citizens and Congress could not ban slavery in territories."],
    ["Emancipation Proclamation (1863)", "Freed enslaved people in Confederate-held areas; made ending slavery a war goal."],
    ["13th, 14th, 15th Amendments", "Abolished slavery (1865); citizenship and equal protection (1868); voting rights regardless of race (1870)."],
    ["Freedmen’s Bureau", "Federal agency that helped formerly enslaved people with schools, food, and contracts."],
    ["Black Codes / sharecropping", "Southern laws restricting freedpeople; a labor system that trapped many in debt."],
    ["Compromise of 1877", "Ended Reconstruction: federal troops left the South in exchange for Hayes becoming president."]
  ],
  steps: [
    { name: "Answering a “to what extent” essay (LEQ)", list: ["Make a claim that shows a degree: “largely,” “partly,” “to a limited extent.”", "Give at least two reasons with specific evidence.", "Acknowledge the other side (complexity).", "Explain how each piece of evidence supports your claim."] }
  ],
  examples: [
    { q: "SAQ: Briefly explain ONE way the Mexican-American War increased sectional tension.", steps: ["Answer: it raised the question of slavery in the new territory.", "Cite: the Wilmot Proviso.", "Explain: Northerners wanted to ban slavery there, Southerners opposed it, and the vote split by region, not party."], answer: "The Mexican-American War added huge new territory, and the Wilmot Proviso (1846) proposed banning slavery there. Votes split along North–South lines, showing that the expansion of slavery was dividing the nation." },
    { q: "SAQ: Briefly explain ONE reason Reconstruction is considered a failure for formerly enslaved people.", steps: ["Answer: rights on paper were not enforced.", "Cite: Black Codes, sharecropping, or the Compromise of 1877.", "Explain: once federal troops left, Southern governments took away Black political rights."], answer: "After the Compromise of 1877 removed federal troops from the South, Southern governments used violence and laws to keep Black citizens from voting, so the promises of the 14th and 15th Amendments went largely unenforced." },
    { q: "Thesis practice: Evaluate the extent to which the Civil War changed the United States (1861–1877).", steps: ["Claim with degree + reasons + complexity.", "Change: slavery ended, federal power grew, citizenship was defined.", "Continuity: racial inequality and Southern economic dependence on cotton persisted."], answer: "“The Civil War greatly changed the nation by ending slavery and strengthening the federal government, but racial inequality continued as Southern states used Black Codes and sharecropping to keep freedpeople in a subordinate position.”" }
  ],
  mistakes: [
    ["Says the Emancipation Proclamation freed all enslaved people.", "“Which areas did it cover? What about the border states? What finally ended slavery everywhere?”"],
    ["Mixes up the three amendments.", "“13 ends slavery, 14 citizenship and equal protection, 15 voting. 13-14-15: free, citizen, vote.”"],
    ["Says the war was only about states’ rights.", "“States’ right to do what? Look at the secession documents.”"],
    ["Ends the story in 1865.", "“What happened to freedpeople during Reconstruction, and why did it end?”"]
  ],
  ask: ["How does this event connect to slavery’s expansion into the West?", "Which compromise came before this, and why did it fail?", "What did this amendment promise? Was it enforced?", "Who gained power during Reconstruction? Who took it back?", "What changed and what stayed the same after the war?"],
  check: [
    { q: "What did Dred Scott decide about Congress and slavery?", a: "Congress could not ban slavery in the territories." },
    { q: "Which amendment granted citizenship?", a: "The 14th" },
    { q: "What ended Reconstruction?", a: "The Compromise of 1877" }
  ],
  visual: "USV_P5" },

/* ---------------- PERIOD 6 ---------------- */
{ id: "us-06", course: "AP U.S. History", unit: 6, title: "Period 6 (1865–1898): The Gilded Age", standards: "≈ 10–17% of the exam",
  bigIdea: "After the Civil War, the U.S. became an industrial giant. Big business (railroads, steel, oil) created enormous wealth but also inequality, dangerous work, and corruption. Millions of “new immigrants” and rural Americans moved to growing cities. Workers formed unions, farmers formed the Populist movement, and the West was settled at the expense of American Indian nations.",
  tips: "Tie everything to one question: <b>“Who benefited from industrialization, and who paid the price?”</b> Industrialists (Carnegie, Rockefeller) vs. workers (strikes, unions), farmers (Populists), immigrants (nativism), and American Indians (Dawes Act). This gives students arguments for almost any prompt.",
  vocab: [
    ["Gilded Age", "Mark Twain’s term: shiny on the outside (wealth) but corrupt underneath."],
    ["vertical / horizontal integration", "Vertical: control every step of production (Carnegie Steel). Horizontal: buy out competitors (Rockefeller’s Standard Oil)."],
    ["laissez-faire & Social Darwinism", "Government should stay out of the economy; “survival of the fittest” used to justify inequality."],
    ["Gospel of Wealth", "Carnegie’s idea that the rich should use their fortunes for public good (philanthropy)."],
    ["Knights of Labor / AFL (1886)", "Knights: open to almost all workers. AFL (Samuel Gompers): skilled workers, focused on wages and hours."],
    ["Haymarket (1886) / Pullman Strike (1894)", "Labor conflicts; Haymarket hurt unions’ image; the federal government broke the Pullman Strike."],
    ["new immigrants", "From Southern and Eastern Europe (and Asia); faced nativism. Chinese Exclusion Act (1882)."],
    ["settlement houses", "Hull House (Jane Addams, 1889): helped immigrants in cities."],
    ["Dawes Act (1887)", "Broke up reservation land into individual plots to force assimilation; Native nations lost most of their land."],
    ["Populist Party / Omaha Platform (1892)", "Farmers’ party: free silver, income tax, government control of railroads."],
    ["Plessy v. Ferguson (1896)", "Supreme Court upheld segregation (“separate but equal”)."]
  ],
  steps: [
    { name: "Answering an SAQ with a document or image", list: ["Read the source line first: who, when, what type of source.", "Identify the main idea or point of view.", "Connect it to a specific historical development from the period.", "Answer exactly what each part (a, b, c) asks, one or two sentences each."] }
  ],
  examples: [
    { q: "SAQ: Briefly explain ONE way workers responded to industrialization.", steps: ["Answer: they organized unions.", "Cite: the American Federation of Labor (1886).", "Explain: unions used collective bargaining and strikes to fight for better wages, hours, and conditions."], answer: "Workers formed unions such as the American Federation of Labor (1886), which organized skilled workers to bargain collectively for higher wages and an eight-hour day, sometimes using strikes." },
    { q: "SAQ: Briefly explain ONE goal of the Populist movement.", steps: ["Answer: help struggling farmers.", "Cite: the Omaha Platform (1892).", "Explain: free coinage of silver would cause inflation, making farmers’ debts easier to repay."], answer: "The Populists’ Omaha Platform (1892) called for free coinage of silver, which would increase the money supply and make it easier for indebted farmers to pay back loans." },
    { q: "Which best explains the purpose of the Dawes Act (1887)?", steps: ["Think about the goal: assimilation.", "It divided tribal land into individual family plots and sold the ‘surplus’ to white settlers."], answer: "To assimilate American Indians by breaking up tribal land into individual farms" }
  ],
  mistakes: [
    ["Mixes up vertical and horizontal integration.", "“Vertical = up and down the supply chain. Horizontal = across, buying competitors.”"],
    ["Thinks the government supported unions in this period.", "“What did the federal government do during the Pullman Strike?”"],
    ["Forgets the West and American Indians.", "“What was happening on the Great Plains at the same time?”"],
    ["Describes a source without connecting it to history.", "“What was happening at the time this was made?”"]
  ],
  ask: ["Who benefited from this development? Who paid the price?", "How did the government respond: help business or workers?", "Where did new immigrants come from? How were they treated?", "What did farmers want, and why?", "How does this source connect to what was happening then?"],
  check: [
    { q: "Who led Hull House?", a: "Jane Addams" },
    { q: "What did Plessy v. Ferguson uphold?", a: "“Separate but equal” segregation" },
    { q: "Which group did the 1882 Exclusion Act target?", a: "Chinese immigrants" }
  ],
  visual: "USV_P6" },

/* ---------------- PERIOD 7 ---------------- */
{ id: "us-07", course: "AP U.S. History", unit: 7, title: "Period 7 (1890–1945): Empire, Progressivism, Depression & World Wars", standards: "≈ 10–17% of the exam",
  bigIdea: "The U.S. became a world power, debated imperialism, and fought in two world wars. At home, Progressives used government to fix problems created by industrialization. The 1920s brought new culture and new conflicts. The Great Depression led to the New Deal, which permanently expanded the federal government’s role in the economy. World War II ended the Depression and made the U.S. a superpower.",
  tips: "The biggest idea in this period is the <b>changing role of government</b>: from laissez-faire, to Progressive regulation, to the New Deal welfare state. Have students place each event on that spectrum. Remind them this is the period with the most content, so they should focus on big patterns instead of memorizing every agency.",
  vocab: [
    ["Spanish-American War (1898)", "U.S. gained Puerto Rico, Guam, and the Philippines; debate over imperialism."],
    ["Progressivism", "Reform movement: muckrakers (Upton Sinclair, Ida Tarbell), trust-busting (Theodore Roosevelt), food safety laws, direct democracy."],
    ["16th–19th Amendments", "Income tax (1913); direct election of senators (1913); Prohibition (1919); women’s suffrage (1920)."],
    ["World War I (U.S. entry 1917)", "Entered after unrestricted submarine warfare and the Zimmermann Telegram. Wilson’s Fourteen Points; Senate rejected the League of Nations."],
    ["First Red Scare (1919–1920)", "Fear of communism and radicals; Palmer Raids."],
    ["1920s culture", "Harlem Renaissance, consumer culture, Scopes Trial, Ku Klux Klan revival, immigration quotas (1924)."],
    ["Great Migration", "Millions of Black Southerners moved to Northern cities for jobs and to escape Jim Crow."],
    ["Great Depression (1929)", "Stock market crash, bank failures, about 25% unemployment at its worst."],
    ["New Deal", "FDR’s programs: relief, recovery, reform (Social Security, FDIC, WPA, Wagner Act)."],
    ["World War II (U.S. entry 1941)", "After Pearl Harbor. Mobilization ended the Depression; women and minorities entered war jobs."],
    ["Japanese American internment (1942)", "Executive Order 9066 forced about 120,000 Japanese Americans into camps."]
  ],
  steps: [
    { name: "Planning a DBQ (quick version)", list: ["Read the prompt and underline the task (cause? change? extent?).", "Read each document: write the main idea + one HIPP note (Historical situation, Intended audience, Purpose, or Point of view).", "Group documents into 2–3 categories (these become body paragraphs).", "Write contextualization (what was happening before/around the prompt) and a thesis with reasoning.", "Add one piece of outside evidence not in the documents."] }
  ],
  examples: [
    { q: "SAQ: Briefly explain ONE way the New Deal changed the role of the federal government.", steps: ["Answer: the government took responsibility for economic security.", "Cite: Social Security Act (1935).", "Explain: for the first time, the federal government provided pensions and unemployment insurance."], answer: "The Social Security Act (1935) made the federal government responsible for providing pensions for the elderly and unemployment insurance, a major shift away from laissez-faire toward a welfare state." },
    { q: "SAQ: Briefly explain ONE argument against U.S. imperialism after 1898.", steps: ["Answer: it contradicted American ideals of self-government.", "Cite: the Anti-Imperialist League / the Philippine-American War.", "Explain: ruling the Philippines without their consent violated the principles of the Declaration."], answer: "Members of the Anti-Imperialist League, such as Mark Twain, argued that ruling the Philippines without their consent violated the American ideal of self-government in the Declaration of Independence." },
    { q: "Contextualization practice: Write 2–3 sentences of context for a DBQ on women’s suffrage (1890–1920).", steps: ["Start BEFORE the prompt’s time period.", "Connect to a broader development.", "End by linking to the topic of the prompt."], answer: "“Since the Seneca Falls Convention of 1848, women had demanded the vote, but the 15th Amendment (1870) extended voting rights only to Black men. As the Progressive movement grew in the 1890s, women gained new public roles as reformers, strengthening their argument for suffrage.”" }
  ],
  mistakes: [
    ["Lists New Deal programs without explaining their significance.", "“What did this program change about what government does?”"],
    ["Mixes up the Progressive amendments.", "“16 tax, 17 senators, 18 Prohibition, 19 women’s suffrage.”"],
    ["Writes contextualization that’s just one sentence about the topic itself.", "“What was happening BEFORE and around this? Zoom out.”"],
    ["Summarizes documents instead of using them as evidence.", "“How does this document prove your argument?”"]
  ],
  ask: ["Is the government getting bigger or smaller here? Why?", "What problem were reformers trying to fix?", "How did the war change life at home?", "What’s the broader context before this event?", "Which documents agree with each other?"],
  check: [
    { q: "Which amendment gave women the vote?", a: "The 19th (1920)" },
    { q: "What executive order led to Japanese American internment?", a: "Executive Order 9066 (1942)" },
    { q: "Name one muckraker.", a: "Upton Sinclair, Ida Tarbell, Jacob Riis, or Lincoln Steffens" }
  ],
  visual: "USV_P7" },

/* ---------------- PERIOD 8 ---------------- */
{ id: "us-08", course: "AP U.S. History", unit: 8, title: "Period 8 (1945–1980): Cold War, Civil Rights & a Changing Society", standards: "≈ 10–17% of the exam",
  bigIdea: "After WWII, the U.S. led the fight against communism (the Cold War), which shaped foreign policy (containment, Korea, Vietnam) and life at home (the Red Scare, the arms race). Economic prosperity created suburbs and a large middle class. The civil rights movement used courts, protest, and legislation to end legal segregation, inspiring other movements. By the 1970s, Vietnam and Watergate had reduced trust in government.",
  tips: "Students often mix up Cold War events. Have them sort each into <b>containment tools</b>: economic (Marshall Plan), military alliance (NATO), military action (Korea, Vietnam), or domestic (McCarthyism, the space race). For civil rights, sort by <b>strategy</b>: courts (Brown), nonviolent protest (Montgomery, sit-ins, March on Washington), legislation (Civil Rights Act, Voting Rights Act), and Black Power.",
  vocab: [
    ["containment", "U.S. policy to stop the spread of communism (George Kennan)."],
    ["Truman Doctrine (1947) / Marshall Plan", "Aid to countries resisting communism (Greece, Turkey) / economic aid to rebuild Western Europe."],
    ["NATO (1949)", "Military alliance of the U.S. and Western Europe against the USSR."],
    ["Korean War (1950–1953)", "First major ‘hot’ war of containment; ended near the original border."],
    ["McCarthyism", "Second Red Scare: accusations of communist infiltration with little evidence."],
    ["Brown v. Board of Education (1954)", "Supreme Court ended segregation in public schools, overturning Plessy."],
    ["Montgomery Bus Boycott (1955)", "Rosa Parks and Martin Luther King Jr.; nonviolent protest."],
    ["Civil Rights Act (1964) / Voting Rights Act (1965)", "Banned segregation in public places and job discrimination / protected Black voting rights."],
    ["Great Society", "LBJ’s programs: Medicare, Medicaid, War on Poverty."],
    ["Vietnam War / Gulf of Tonkin Resolution (1964)", "Escalation under LBJ; growing protests; ended for the U.S. in 1973."],
    ["Watergate (1972–1974)", "Scandal that led to Nixon’s resignation and declining trust in government."],
    ["other movements", "Women’s movement (NOW, The Feminine Mystique), Chicano movement (César Chávez, UFW), American Indian Movement, environmentalism (EPA, 1970)."]
  ],
  steps: [
    { name: "Writing a body paragraph (DBQ or LEQ)", list: ["Topic sentence: a claim that supports your thesis.", "Evidence: specific facts (or documents) with details.", "Analysis: explain HOW the evidence proves your claim (“This shows… because…”).", "Link back to the thesis."] }
  ],
  examples: [
    { q: "SAQ: Briefly explain ONE way the Cold War affected life in the United States.", steps: ["Answer: fear of communism at home.", "Cite: McCarthyism / the Second Red Scare.", "Explain: people lost jobs and careers based on accusations, limiting free speech."], answer: "During the Second Red Scare, Senator Joseph McCarthy accused government workers and others of being communists, often without evidence, which created fear and led people to lose their jobs for their political beliefs." },
    { q: "SAQ: Briefly explain ONE difference between two strategies of the civil rights movement.", steps: ["Answer: legal challenges vs. direct action.", "Cite: Brown v. Board (NAACP lawyers) vs. the Montgomery Bus Boycott.", "Explain: one used the courts to change laws; the other used mass nonviolent protest to pressure businesses and public opinion."], answer: "The NAACP challenged segregation in court, winning Brown v. Board of Education (1954), while activists in the Montgomery Bus Boycott (1955) used mass nonviolent protest and economic pressure to end segregation on buses." },
    { q: "Which best explains why the U.S. fought in Korea?", steps: ["Match the event to the policy.", "North Korea (communist) invaded South Korea; the U.S. wanted to stop communism from spreading."], answer: "To contain the spread of communism" }
  ],
  mistakes: [
    ["Says the Cold War was a direct war between the U.S. and USSR.", "“Did they ever fight each other directly? Where did the fighting happen?”"],
    ["Thinks civil rights ended with Brown v. Board.", "“Was the ruling enforced right away? What laws came 10 years later?”"],
    ["Forgets other movements inspired by civil rights.", "“Which other groups used similar strategies in the 1960s–70s?”"],
    ["Writes evidence with no analysis.", "“Great evidence. Now, how does it prove your claim?”"]
  ],
  ask: ["How is this event connected to containment?", "Which civil rights strategy is this: courts, protest, or legislation?", "Did this increase or decrease trust in government?", "Who else was inspired by this movement?", "Can you explain HOW your evidence supports your claim?"],
  check: [
    { q: "What did Brown v. Board overturn?", a: "Plessy v. Ferguson (“separate but equal”)" },
    { q: "What alliance formed in 1949?", a: "NATO" },
    { q: "What scandal led Nixon to resign?", a: "Watergate" }
  ],
  visual: "USV_P8" },

/* ---------------- PERIOD 9 ---------------- */
{ id: "us-09", course: "AP U.S. History", unit: 9, title: "Period 9 (1980–Present): Conservatism, Globalization & a New Century", standards: "≈ 4–6% of the exam",
  bigIdea: "The election of Ronald Reagan (1980) marked the rise of modern conservatism: tax cuts, deregulation, and a strong anti-communist foreign policy. The Cold War ended in 1991, and the U.S. faced a new world of globalization, new technology, and, after September 11, 2001, the War on Terror. Debates over immigration, the economy, and the role of government continue today.",
  tips: "This period is small on the exam. Focus on <b>two big ideas</b>: the conservative shift (Reagan, smaller government, the religious right) and globalization (NAFTA, outsourcing, technology, immigration). Have students connect these to earlier debates about the size of government (New Deal, Great Society).",
  vocab: [
    ["New Right / Reagan Revolution", "Conservative coalition: tax cuts, deregulation, smaller government, traditional values."],
    ["Reaganomics", "Supply-side economics: tax cuts for businesses and the wealthy were supposed to “trickle down.”"],
    ["end of the Cold War (1989–1991)", "Fall of the Berlin Wall (1989); collapse of the Soviet Union (1991)."],
    ["NAFTA (1994)", "Free trade agreement with Canada and Mexico; part of globalization."],
    ["globalization & technology", "Global trade, outsourcing of manufacturing jobs, the internet and digital economy."],
    ["September 11, 2001", "Terrorist attacks; led to wars in Afghanistan and Iraq and the Department of Homeland Security."],
    ["demographic change", "Growth of the Sunbelt; increased immigration from Latin America and Asia."],
    ["Great Recession (2008)", "Financial crisis and federal bailouts; debates over the role of government in the economy."]
  ],
  steps: [
    { name: "Comparing across periods (a common essay skill)", list: ["Name the earlier development and the later one.", "Explain a similarity AND a difference.", "Explain WHY: what conditions were the same or different?", "Example: Reagan’s smaller-government ideas vs. FDR’s New Deal."] }
  ],
  examples: [
    { q: "SAQ: Briefly explain ONE way Reagan’s policies differed from the New Deal.", steps: ["Answer: Reagan wanted a smaller federal government.", "Cite: tax cuts and deregulation in the 1980s.", "Explain: FDR expanded government to fix the economy; Reagan argued government was the problem."], answer: "While the New Deal expanded the federal government’s role in managing the economy, Reagan cut taxes and deregulated industries in the 1980s, arguing that a smaller government would encourage economic growth." },
    { q: "SAQ: Briefly explain ONE effect of globalization on the U.S. economy since 1980.", steps: ["Answer: manufacturing jobs moved overseas.", "Cite: NAFTA (1994) or outsourcing to Asia.", "Explain: companies moved production to lower-wage countries, hurting industrial regions."], answer: "After NAFTA (1994) and growing trade with Asia, many U.S. companies moved manufacturing overseas to cut costs, which led to job losses in Rust Belt industrial cities while consumers got cheaper goods." },
    { q: "Which event most directly led to the creation of the Department of Homeland Security?", steps: ["Look for a security event after 2000.", "The attacks on September 11, 2001 led to a reorganization of domestic security."], answer: "The September 11, 2001 terrorist attacks" }
  ],
  mistakes: [
    ["Writes opinions about current politics instead of history.", "“AP wants evidence and analysis, not your opinion of politicians. What does the evidence show?”"],
    ["Ignores connections to earlier periods.", "“What earlier debate does this remind you of?”"],
    ["Gives vague answers like ‘technology changed things.’", "“Which technology? What specifically changed?”"]
  ],
  ask: ["How is this similar to (or different from) an earlier period?", "Is this about the size of government, the economy, or foreign policy?", "Who benefited and who was hurt?", "What specific example can you name?"],
  check: [
    { q: "When did the Soviet Union collapse?", a: "1991" },
    { q: "What countries were part of NAFTA?", a: "U.S., Canada, Mexico" },
    { q: "What is supply-side economics?", a: "Cutting taxes (especially on business/wealthy) to spur growth" }
  ],
  visual: "USV_P9" },

/* ---------------- WRITING SKILLS ---------------- */
{ id: "us-10", course: "AP U.S. History", unit: 10, title: "Writing Skills: SAQ, DBQ & LEQ (How to Help with Any Essay)", standards: "All periods · free-response section",
  bigIdea: "APUSH essays are scored with a rubric, so tutors can help even without knowing every fact. Short-answer questions (SAQs) need direct, specific answers. The DBQ (document-based question) and LEQ (long essay question) reward the same core skills: a defensible thesis with a line of reasoning, contextualization, specific evidence, and analysis. The DBQ adds using and sourcing documents.",
  tips: "You don’t have to be a history expert. Focus on the <b>rubric skills</b>: Does the thesis make an argument? Is there context from before the time period? Does every piece of evidence have a “this shows…” sentence after it? Point values change occasionally, so check the student’s current class rubric. Read the student’s thesis out loud and ask, “Could someone disagree with this?” If not, it isn’t an argument yet.",
  vocab: [
    ["SAQ (ACE)", "Answer the question directly, Cite specific evidence, Explain how the evidence supports the answer. 1–3 sentences per part."],
    ["thesis / claim", "A historically defensible argument that answers the prompt and gives a line of reasoning (the “because” part). Usually 1–2 sentences."],
    ["contextualization", "Describe the broader historical situation BEFORE or around the prompt’s time period, then connect it to the topic. Several sentences, not a phrase."],
    ["evidence", "Specific facts (names, events, laws, dates) used to support the argument. In the DBQ: content from the documents plus at least one piece of outside evidence."],
    ["HIPP (sourcing)", "Historical situation, Intended audience, Purpose, Point of view. Explain how one of these affects the document’s meaning."],
    ["complexity", "Showing a nuanced understanding: multiple causes, both change and continuity, corroborating/contradicting documents, or connections to another period."],
    ["historical reasoning skills", "Causation (why?), comparison (similar/different?), continuity and change over time (what changed?)."],
    ["DBQ (≈ 7 points)", "Thesis, contextualization, evidence from documents, outside evidence, sourcing, complexity."],
    ["LEQ (≈ 6 points)", "Thesis, contextualization, evidence (specific examples), analysis and reasoning (including complexity)."]
  ],
  steps: [
    { name: "Writing a strong thesis", list: ["Answer the exact question (cause, change, extent, comparison).", "Make it arguable: someone could disagree.", "Give a line of reasoning: 2–3 reasons (“because A, B, and C”).", "For complexity, try: “Although ___, ___ because ___.”"] },
    { name: "Writing contextualization", list: ["Start 10–30 years before the prompt’s time period.", "Describe a big development (war, economic change, movement).", "Use 3–4 sentences with specific evidence.", "End with a sentence connecting it to the prompt’s topic."] },
    { name: "Sourcing a document (HIPP)", list: ["Pick ONE of H, I, P, or P that clearly matters.", "Name it: “Because this was written by a factory owner…”", "Explain the effect: “…he likely downplayed dangerous conditions.”", "Do this for at least 2 documents (check your rubric)."] }
  ],
  examples: [
    { q: "Fix this thesis. Prompt: “Evaluate the extent to which the Market Revolution changed the U.S. economy (1800–1848).” Student thesis: “The Market Revolution changed the economy in many ways.”", steps: ["Problem: it restates the prompt and has no reasons.", "Add a degree: “greatly,” “to a large extent.”", "Add reasons: transportation, factories, regional specialization.", "Add complexity: what stayed the same?"], answer: "“The Market Revolution greatly changed the U.S. economy by linking regions through canals and railroads and by expanding factory work in the North, although the South remained dependent on agriculture and enslaved labor.”" },
    { q: "Source this document: an 1890s speech by a Populist leader to a group of farmers calling railroads ‘monopolies that rob the farmer.’ Use HIPP.", steps: ["Pick the best letter: Intended audience (farmers) or Purpose (persuade them to support Populists).", "Name it, then explain how it affects the document."], answer: "“Because the speaker’s purpose was to win farmers’ votes for the Populist Party, he exaggerated the railroads’ wrongdoing to make farmers angry and motivated to support Populist reforms.”" },
    { q: "Turn this evidence into analysis: “The Homestead Act gave people 160 acres of land.”", steps: ["Add a specific detail: when, for whom.", "Add “This shows…” connecting to the argument.", "Explain the reasoning (why it matters)."], answer: "“The Homestead Act (1862) offered 160 acres of free western land to settlers who farmed it for five years. This shows that the federal government actively promoted western settlement, which increased conflict with American Indian nations on the Plains.”" }
  ],
  mistakes: [
    ["Thesis restates the prompt.", "“Could anyone disagree with that? What’s YOUR argument and why?”"],
    ["Contextualization is one vague sentence (“Throughout history, people have…”).", "“What specifically was happening right before this time period?”"],
    ["Summarizes each document one by one.", "“Group the documents by idea. Which ones support the same reason?”"],
    ["Sourcing just says who wrote it.", "“OK, it’s a factory owner. How does THAT change what he says?”"],
    ["SAQ answers are long but never directly answer the question.", "“Start with the answer in your first sentence. Then prove it.”"]
  ],
  ask: ["What is the prompt really asking: cause, change, comparison, or extent?", "Could someone disagree with your thesis?", "What was happening before this time period?", "After that evidence, can you add a ‘This shows…’ sentence?", "Which letter of HIPP matters most for this document? Why?"],
  check: [
    { q: "What does ACE stand for?", a: "Answer, Cite, Explain" },
    { q: "What are the letters in HIPP?", a: "Historical situation, Intended audience, Purpose, Point of view" },
    { q: "What makes a thesis ‘defensible’?", a: "It makes an arguable claim supported by evidence, with a line of reasoning." }
  ],
  visual: "USV_WRITE" }
);

/* ===== APUSH timelines ===== */
(function () {
  const t = (x, y, s, o) => `<text x="${x}" y="${y}" font-size="${(o && o.fs) || 11}" text-anchor="${(o && o.a) || "middle"}" font-weight="${o && o.b ? 700 : 400}" fill="${(o && o.c) || "#333"}">${s}</text>`;
  const COL = ["#2b7de9", "#e8368f", "#e08a00", "#1aa36f", "#8a54e0", "#d0453a"];
  function timeline(title, a, b, ev) {
    const W = 560, X = y => 30 + (y - a) / (b - a) * (W - 60); let g = t(W / 2, 20, title, { b: 1, fs: 13 }) + `<line x1="20" y1="120" x2="${W - 20}" y2="120" stroke="#333" stroke-width="3"/>`;
    [a, b].forEach(y => g += t(X(y), 140, y, { b: 1 }));
    ev.forEach(([y, l], i) => { const up = i % 2 === 0, lvl = Math.floor(i / 2) % 2, yy = up ? 100 - lvl * 32 : 160 + lvl * 32, c = COL[i % COL.length];
      g += `<line x1="${X(y)}" y1="120" x2="${X(y)}" y2="${up ? yy + 4 : yy - 14}" stroke="${c}" stroke-width="1.5"/><circle cx="${X(y)}" cy="120" r="5" fill="${c}"/>` + t(X(y), yy - (up ? 10 : 0), String(y).replace(".5", ""), { b: 1, c, fs: 10 }) + t(X(y), yy + (up ? 3 : 13), l, { fs: 10 }); });
    return `<svg viewBox="0 0 ${W} 240" width="${W}" role="img" aria-label="timeline: ${title}" style="background:#fff;border-radius:12px;max-width:100%;height:auto">${g}</svg>`;
  }
  const V = {
    USV_P1: timeline("Period 1: 1491–1607", 1490, 1610, [[1492, "Columbus arrives"], [1512, "Laws of Burgos"], [1521, "Spain conquers Aztecs"], [1550, "Valladolid debate"], [1565, "St. Augustine"], [1598, "Spain in New Mexico"], [1607, "Jamestown"]]),
    USV_P2: timeline("Period 2: 1607–1754", 1600, 1760, [[1607, "Jamestown"], [1619, "first Africans in VA"], [1630, "Mass. Bay Colony"], [1651, "Navigation Acts"], [1676, "Bacon’s Rebellion"], [1680, "Pueblo Revolt"], [1739, "Stono Rebellion"], [1740, "Great Awakening"]]),
    USV_P3: timeline("Period 3: 1754–1800", 1750, 1802, [[1754, "French & Indian War"], [1763, "Proclamation Line"], [1765, "Stamp Act"], [1776, "Declaration"], [1781, "Articles ratified"], [1786, "Shays’ Rebellion"], [1787, "Constitution"], [1791, "Bill of Rights"], [1798, "Alien & Sedition"]]),
    USV_P4: timeline("Period 4: 1800–1848", 1798, 1850, [[1803, "Louisiana Purchase"], [1803, "Marbury v. Madison"], [1812, "War of 1812"], [1820, "Missouri Compromise"], [1823, "Monroe Doctrine"], [1825, "Erie Canal"], [1830, "Indian Removal Act"], [1832, "Nullification crisis"], [1848, "Seneca Falls"]]),
    USV_P5: timeline("Period 5: 1844–1877", 1843, 1879, [[1846, "Mexican-American War"], [1850, "Compromise of 1850"], [1854, "Kansas-Nebraska Act"], [1857, "Dred Scott"], [1861, "Civil War begins"], [1863, "Emancipation Proc."], [1865, "13th Amendment"], [1868, "14th Amendment"], [1877, "Reconstruction ends"]]),
    USV_P6: timeline("Period 6: 1865–1898", 1864, 1900, [[1869, "transcontinental RR"], [1876, "Little Bighorn"], [1882, "Chinese Exclusion"], [1886, "Haymarket / AFL"], [1887, "Dawes Act"], [1889, "Hull House"], [1892, "Omaha Platform"], [1894, "Pullman Strike"], [1896, "Plessy v. Ferguson"]]),
    USV_P7: timeline("Period 7: 1890–1945", 1888, 1947, [[1898, "Spanish-American War"], [1906, "Meat Inspection Act"], [1917, "U.S. enters WWI"], [1920, "19th Amendment"], [1924, "immigration quotas"], [1929, "stock market crash"], [1935, "Social Security"], [1941, "Pearl Harbor"], [1945, "WWII ends"]]),
    USV_P8: timeline("Period 8: 1945–1980", 1944, 1981, [[1947, "Truman Doctrine"], [1949, "NATO"], [1950, "Korean War"], [1954, "Brown v. Board"], [1955, "Montgomery boycott"], [1964, "Civil Rights Act"], [1965, "Voting Rights Act"], [1970, "EPA created"], [1974, "Nixon resigns"]]),
    USV_P9: timeline("Period 9: 1980–present", 1978, 2012, [[1980, "Reagan elected"], [1989, "Berlin Wall falls"], [1991, "USSR collapses"], [1994, "NAFTA"], [2001, "9/11 attacks"], [2003, "Iraq War"], [2008, "Great Recession"]]),
    USV_WRITE: `<table style="border-collapse:collapse;font-size:.9rem;max-width:560px">${[["Skill", "What graders look for", "Quick test"], ["Thesis", "Arguable claim + line of reasoning", "Could someone disagree?"], ["Contextualization", "Broader situation before/around the prompt, connected to it", "Does it start before the date range?"], ["Evidence", "Specific names, events, laws, documents", "Could you look it up in a textbook index?"], ["Analysis", "Explains HOW evidence proves the claim", "Is there a “This shows…” sentence?"], ["Sourcing (DBQ)", "HIPP explained for documents", "Does it say WHY the source matters?"], ["Complexity", "Nuance: both sides, multiple causes, connections", "Is there an “although…” idea?"]].map((r, i) => `<tr>${r.map(c => `<${i ? "td" : "th"} style="border:1px solid #ccc;padding:6px 8px;text-align:left;vertical-align:top;background:${i ? "#fff" : "#f3f3f6"};color:#222">${c}</${i ? "td" : "th"}>`).join("")}</tr>`).join("")}</table>`
  };
  (window.TUTOR_UNITS || []).forEach(u => { if (u.course === "AP U.S. History" && V[u.visual]) u.visual = V[u.visual]; });
})();
